  "Agrandissez votre salle place par place pour accueillir plus de spectateurs (brique Agrandir la salle : chaque type de gradin a son prix par place et son nombre maximum de places), et réglez le prix du billet CATÉGORIE PAR CATÉGORIE : gradins populaires, tribune couverte et loges VIP n'ont ni la même capacité, ni la même tolérance au prix. Seuls les matchs à domicile rapportent une recette. L'humeur des supporters influence le remplissage et la tolérance au prix. D'autres infrastructures sont proposées, chacune sur 5 niveaux comme le centre de formation : Boutique des supporters (revenu fixe chaque semaine), Station TV (revenu fixe chaque semaine), Salle de musculation (réduit le risque de blessure) et Espace bien-être (réduit la fatigue en match).": "Expand your arena seat by seat to hold more fans (Expand the arena block: each stand type has its own price per seat and maximum number of seats), and set ticket prices CATEGORY BY CATEGORY: general stands, covered stands and VIP boxes don't share the same capacity or price tolerance. Only home matches bring in revenue. Fan mood affects turnout and price tolerance. Other facilities are also available, each with 5 levels like the youth academy: Fan Shop (fixed weekly revenue), TV Station (fixed weekly revenue), Weight Room (reduces injury risk) and Wellness Center (reduces in-game fatigue).",
