  "Avant chaque match, réglez trois choses pour votre équipe dans l'onglet Ordres. Tout s'enregistre automatiquement à chaque changement, et le bouton \"Enregistrer\", toujours visible en bas de la page, confirme l'enregistrement (\"Annuler\" revient aux ordres tels qu'à l'ouverture de la page). Dans le Calendrier, un match aux ordres validés affiche \"Modifier vos ordres\".": "Before each game, set three things for your team in the Orders tab. Everything saves automatically with each change, and the \"Save\" button, always visible at the bottom of the page, confirms the save (\"Cancel\" goes back to the orders as they were when you opened the page). In the Schedule, a game with confirmed orders shows \"Edit your orders\".",
