  "Budget du club et son évolution, masse salariale (joueurs et staff), revenus de la salle, de la boutique et des droits TV, et l'historique des transactions groupé par semaine. Un budget durablement sous le seuil d'alerte finit par mettre tout l'effectif en vente forcée à 1 € : surveillez la masse salariale.": "Club budget and its trend, payroll (players and staff), revenue from the arena, the shop and TV rights, and transaction history grouped by week. A budget that stays below the alert threshold will eventually force the whole squad up for sale at €1: keep an eye on the payroll.",
