  "Catégorie de fil d'actualité inconnue : {0}": "Unknown news feed category: {0}",
  "Catégorie de place inconnue : {0}.": "Unknown seat category: {0}.",
  "Ce bouton ne change RIEN au moteur du match : il choisit juste combien de réglages tactiques s'affichent à l'écran. Une équipe restée en Débutant joue avec des valeurs standards, exactement comme si elle avait activé le mode confirmé sans rien changer.": "This button changes NOTHING about the match engine: it just chooses how many tactical settings are shown on screen. A team left on Beginner plays with standard values, exactly as if it had switched to Advanced mode without changing anything.",
  "Ce genre de match, ça se prépare mentalement dès le réveil, j'étais focus du début à la fin.": "That kind of game, you prepare for it mentally from the moment you wake up, I was focused from start to finish.",
  "Ce joueur": "This player",
  "Ce joueur est actuellement aux enchères sur le marché des transferts, ses caractéristiques sont donc visibles.": "This player is currently up for auction on the transfer market, so his attributes are visible.",
  "Ce joueur est déjà au Hall of Fame.": "This player is already in the Hall of Fame.",
  "Ce joueur n'a jamais joué de match officiel pour le club.": "This player has never played an official match for the club.",
