  "Ce joueur n'est plus dans cet effectif (vendu, ou transféré).": "This player is no longer in this squad (sold, or transferred).",
  "Ce lien n'est pas valide : demande un nouveau lien privé à l'organisateur de la ligue.": "This link isn't valid: ask the league organizer for a new private link.",
  "Ce maillot est déjà retiré.": "This jersey is already retired.",
  "Ce nom de salle n'est pas autorisé.": "This arena name is not allowed.",
  "Ce nom n'est pas autorisé.": "This name is not allowed.",
  "Ce que ça veut dire": "What this means",
  "Ce que la ligue privée ne touche pas": "What the private league doesn't affect",
  "Ce qui la fait baisser": "What brings it down",
  "Ce qui la fait monter": "What brings it up",
  "Ce rapport est déjà débloqué et à jour.": "This report is already unlocked and up to date.",
  "Ce réglage est toujours visible, quel que soit votre niveau tactique. En Adaptatif, l'équipe qui mène large lève le pied dès le 3e quart-temps, les titulaires sortent au 4e quart-temps à 18 points d'écart (forme ménagée), et le rythme s'accélère légèrement dans les 5 dernières minutes d'un match serré.": "This setting is always visible, whatever your tactical level. On Adaptive, the team with a big lead eases off from the 3rd quarter on, starters sit in the 4th quarter at an 18-point gap (fitness saved), and the pace picks up slightly in the last 5 minutes of a close game.",
  "Ce soir, tout est rentré naturellement, mes coéquipiers m'ont trouvé aux bons endroits toute la rencontre.": "Tonight everything just fell in naturally, my teammates found me in the right spots all game long.",
  "Ce titre appartient à tout le monde au club, on va rester humbles et continuer à travailler comme si de rien n'était.": "This title belongs to everyone at the club, we're going to stay humble and keep working as if nothing happened.",
  "Ce titre de champion face à {opponent} en finale récompense tout le travail accompli cette saison, une immense fierté pour tout le club.": "This championship title against {opponent} in the final rewards all the work done this season, a huge source of pride for the whole club.",
  "Ce titre face à {opponent} appartient à tout le club, des joueurs jusqu'au dernier membre du staff, on ne l'oubliera jamais.": "This title against {opponent} belongs to the whole club, from the players down to the last staff member, we'll never forget it.",
  "Ce titre représente une immense fierté pour tout le club, du staff aux joueurs en passant par les supporters.": "This title represents huge pride for the whole club, from the staff to the players to the fans.",
  "Ce titre représente une nouvelle étape pour ce club, et on compte bien ne pas s'arrêter là la saison prochaine.": "This title marks a new milestone for this club, and we fully intend not to stop there next season.",
  "Ce trigramme est déjà utilisé par un autre club de la ligue.": "This club code is already used by another club in the league.",
  "Ce trigramme n'est pas autorisé.": "This club code is not allowed.",
  "center": "center",
  "Centre de formation": "Youth academy",
  "Centre de formation : {0}": "Youth academy: {0}",
  "Centre de formation : serveur indisponible :": "Youth academy: server unavailable:",
  "Centre de formation déjà au niveau maximum.": "Youth academy already at maximum level.",
  "Centre de récupération": "Recovery center",
  "Centre labellisé": "Certified center",
  "Centre régional": "Regional center",
  "Cercle / raquette": "Rim / paint",
  "Ces infrastructures se financent chacune indépendamment : inutile d'attendre d'avoir fini d'en payer une pour commencer la suivante si le budget suit.": "Each of these facilities is financed independently: no need to wait until one is fully paid off to start the next one if the budget allows.",
  "Cet adversaire a rejoué depuis ton dernier déblocage : les données ont changé.": "This opponent has played again since your last unlock: the data has changed.",
  "Cet emplacement a déjà un sponsor.": "This slot already has a sponsor.",
  "Cette carte montre le prochain match avec un compte à rebours ; sur chaque ligne, le bouton Ordres (ou Modifier vos ordres) prépare le match correspondant.": "This card shows the next game with a countdown; on each row, the Orders button (or Edit your orders) prepares the corresponding game.",
  "Cette défaite contre {opponent} à mi-saison est une bonne piqûre de rappel, on doit rester humbles et travailler encore plus dur pour la suite.": "This loss to {opponent} at mid-season is a good wake-up call, we need to stay humble and work even harder going forward.",
  "Cette défaite contre {opponent} arrive à un moment charnière de la saison, on va en tirer les leçons avant d'attaquer la seconde moitié du calendrier.": "This loss to {opponent} comes at a pivotal moment of the season, we're going to learn from it before tackling the second half of the schedule.",
  "Cette défaite contre {opponent} ne change rien à nos ambitions pour la seconde moitié de saison, on reste le favori de cette division.": "This loss to {opponent} changes nothing about our ambitions for the second half of the season, we remain the favorite in this division.",
  "Cette défaite contre {opponent} pour terminer la saison régulière nous rappelle qu'il reste encore des choses à corriger avant la suite.": "This loss to {opponent} to close out the regular season reminds us there are still things to fix before what's next.",
  "Cette défaite en finale contre {opponent} est difficile à digérer, mais on reviendra chercher ce titre la saison prochaine, sans exception.": "This final loss to {opponent} is hard to swallow, but we'll come back for this title next season, no question.",
  "Cette défaite en finale contre {opponent} est une déception, mais atteindre la finale reste une très belle saison pour ce groupe.": "This final loss to {opponent} is a disappointment, but reaching the final is still a great season for this group.",
  "Cette défaite en finale fait partie du sport, on va rester humbles et repartir travailler dès la saison prochaine.": "This final loss is part of the sport, we're going to stay humble and get back to work starting next season.",
  "Cette défaite en finale reste une bonne saison pour ce club, on va essayer de franchir ce dernier palier la saison prochaine.": "This final loss is still a good season for this club, we're going to try to clear that last hurdle next season.",
  "Cette défaite ne représente rien de plus qu'un contretemps, ce club reviendra chercher ce titre très vite.": "This loss is nothing more than a setback, this club will come back for this title very soon.",
  "Cette dernière défaite de saison régulière contre {opponent} n'entache en rien notre saison, on sait qu'on est prêts pour la suite.": "This final regular-season loss to {opponent} doesn't tarnish our season at all, we know we're ready for what's next.",
  "Cette élimination en demi-finale contre {opponent} est frustrante après une belle saison, on va analyser calmement ce qui a manqué.": "This semi-final elimination against {opponent} is frustrating after a great season, we're going to calmly break down what was missing.",
  "Cette enchère est déjà terminée.": "This bid is already over.",
  "Cette équipe a déjà été scoutée cette saison": "This team has already been scouted this season",
  "Cette équipe a déjà été scoutée cette saison ({0}/{1} caractéristiques révélées, définitif), impossible de la rescouter avant la saison prochaine, même avec un meilleur analyste.": "This team has already been scouted this season ({0}/{1} attributes revealed, final), it can't be scouted again until next season, even with a better analyst.",
  "Cette équipe a déjà été scoutée cette saison.": "This team has already been scouted this season.",
