  "Cette ligue privée a déjà commencé.": "This private league has already started.",
  "Cette ligue privée est complète.": "This private league is full.",
  "Cette offre a expiré.": "This offer has expired.",
  "Cette offre n'existe plus.": "This offer no longer exists.",
  "Cette qualification face à {opponent} en demi-finale doit beaucoup à la réussite autant qu'au mérite, on reste concentrés sur la suite sans s'enflammer.": "This qualification against {opponent} in the semi-final owes as much to luck as to merit, we're staying focused on what's next without getting carried away.",
