  "Changer le logo": "Change the logo",
  "Chaque annonce compare le prix à une valeur estimée (Bonne affaire, Prix correct, Au-dessus de sa valeur). Une enchère gagnée s'ajoute immédiatement à votre masse salariale : vérifiez votre budget avant de vous engager.": "Each listing compares the price to an estimated value (Bargain, Fair price, Above value). A winning bid is added to your payroll immediately: check your budget before committing.",
  "Chaque changement est déjà enregistré automatiquement. « Enregistrer » confirme l'enregistrement auprès du serveur.": "Every change is already saved automatically. “Save” confirms the save with the server.",
  "à chaque jour de repos (jour sans match) : soit préparer une nouvelle tactique, soit privilégier la récupération physique de l'équipe.": "on each rest day (day without a match): either prepare a new tactic, or prioritize the team's physical recovery.",
  "Le club choisit": "The club chooses",
  "Chaque jour, le club travaille un programme parmi les 13 fondamentaux (tir à 3 points, rebond, défense extérieure...) et un ou plusieurs postes à qui l'appliquer. Cibler un seul poste donne le plein rendement ; l'étendre à toute l'équipe touche plus de joueurs mais dilue l'effet. Le Physique et le Mental évoluent, eux, tout seuls au fil de la carrière, indépendamment de ce programme.": "Every day, the club works on one program out of the 13 fundamentals (3-point shooting, rebounding, perimeter defense...) and one or more positions to apply it to. Targeting a single position gives full effectiveness; extending it to the whole team reaches more players but dilutes the effect. Physical and Mental attributes, on the other hand, develop on their own over the course of a career, independent of this program.",
  "Chaque match se joue à son heure, que vous le regardiez ou non. Connecté, suivez-le depuis l'onglet": "Every match is played at its scheduled time, whether you watch it or not. While connected, follow it from the tab",
  "Chaque nom de club doit être une chaîne non vide.": "Every club name must be a non-empty string.",
  "Chaque prospect affiche une estimation de potentiel (Espoir, Grand espoir ou Prodige) et se signe directement, sans enchère ni négociation, contrairement au marché des transferts.": "Each prospect shows a potential estimate (Prospect, Rising star, or Prodigy) and signs directly, without a bid or negotiation, unlike the transfer market.",
  "Chaque variation d'ambiance est journalisée ici avec son motif exact : résultat de match, prix du billet, interview de jalon, demande de transfert, signal ou verdict d'objectif de saison.": "Every mood change is logged here with its exact cause: match result, ticket price, milestone interview, transfer request, signal, or season objective verdict.",
