  "Congédier": "Dismiss",
  "Connaissance tactique": "Tactical knowledge",
  "Connaissance tactique : chaque option jouée monte de +6 à +12 par match, +4 par jour d'entraînement dessus ; une option délaissée ne baisse qu'à partir du 3e match d'absence (-2, -4, puis -6 au maximum). Le détail est dans le Guide.": "Tactical knowledge: each option played goes up by +6 to +12 per match, +4 per day of training on it; a neglected option only starts dropping from the 3rd match of absence onward (-2, -4, then -6 at most). Details are in the Guide.",
  "Conseil : attaquez la raquette sans crainte, pénétrez et finissez au panier plutôt que de vous contenter du tir extérieur.": "Tip: attack the paint fearlessly, drive and finish at the rim rather than settling for outside shots.",
  "Conseil : envoyez du monde au rebond offensif, les secondes chances seront disponibles.": "Tip: send numbers to the offensive glass, second chances will be there.",
  "Conseil : évitez la finition en force au cercle, privilégiez le tir extérieur ou la passe après pénétration (kick-out) plutôt que le layup contesté.": "Tip: avoid forcing it at the rim, favor the outside shot or the kick-out pass after a drive rather than a contested layup.",
  "Conseil : forcez la pénétration balle en main et jouez agressif vers le cercle pour provoquer des fautes et aller sur la ligne des lancers francs.": "Tip: force the drive with the ball and play aggressively toward the rim to draw fouls and get to the free-throw line.",
  "Conseil : ne comptez pas sur les lancers francs, il faudra scorer au jeu plutôt que provoquer la faute.": "Tip: don't count on free throws, you'll need to score from the field rather than draw fouls.",
  "Conseil : ne surinvestissez pas le rebond offensif, repliez-vous plus tôt pour limiter leur contre-attaque.": "Tip: don't overcommit to the offensive boards, get back on defense earlier to limit their fast break.",
  "Conseil : sécurisez la balle et limitez les passes risquées pour ne pas les lancer en contre-attaque.": "Tip: secure the ball and limit risky passes so you don't set them up on the fast break.",
