  "Contrôlé est le réglage neutre. Agressif conteste mieux les tirs extérieurs réellement pris, mais une fermeture trop appuyée ouvre plus facilement la pénétration : le tireur en profite pour foncer vers le panier plutôt que de tirer.": "Controlled is the neutral setting. Aggressive contests outside shots that are actually taken better, but closing out too hard makes it easier to get driven past: the shooter takes advantage to drive to the rim instead of shooting.",
