  "JSON invalide.": "Invalid JSON.",
  "Jusqu'à 150 000 €": "Up to €150,000",
  "Jusqu'à 3 affectations poste + focus (empêcher le post-up, coller sur les pénétrations, harceler le tir extérieur, priorité au rebond, couper du ballon). Chaque focus donne un bonus défensif ciblé, avec une petite contrepartie ailleurs pour le défenseur concerné.": "Up to 3 position assignments + focus (deny the post-up, stick to dribble-drives, contest outside shots, prioritize rebounding, deny the ball). Each focus gives a targeted defensive bonus, with a small trade-off elsewhere for the defender concerned.",
  "Jusqu'à 300 000 €": "Up to €300,000",
  "Jusqu'à 50 000 €": "Up to €50,000",
  "Jusqu'où le joueur peut encore progresser, jamais en chiffre : un palier parmi 10, de Débutant à Générationnel (Prospect, Joueur correct, Solide, Starter, Très bon joueur, Star, All-Star, Superstar). Les jeunes de l'académie n'affichent qu'une estimation : Espoir, Grand espoir ou Prodige.": "How much further the player can still develop, never shown as a number: one tier out of 10, from Rookie to Generational (Prospect, Decent player, Solid, Starter, Very good player, Star, All-Star, Superstar). Academy youngsters only show an estimate: Hopeful, Highly rated prospect or Prodigy.",
  "Kante": "Kante",
  "Karim": "Karim",
