  "Kowalski": "Kowalski",
  "l'adversaire": "the opponent",
  "L'adversaire ne peut pas aligner un cinq de départ complet : vous gagnerez automatiquement par forfait (20-0) à l'heure prévue.": "The opponent can't field a complete starting five: you will automatically win by forfeit (20-0) at the scheduled time.",
  "L’affiche": "The matchup",
  "L'alchimie (0 à 100, visible sur le Tableau de bord et en tête de l'Effectif) mesure la cohésion du groupe. Elle agit sur TOUTE l'équipe en match, de -6 % (vestiaire fracturé) à +6 % (alchimie parfaite). Paliers : Vestiaire fracturé (moins de 25), Tensions dans le groupe (25-44), Cohésion correcte (45-64), Bonne cohésion (65-84), Alchimie parfaite (85 et plus).": "Chemistry (0 to 100, visible on the Dashboard and at the top of the Squad) measures group cohesion. It affects the WHOLE team in matches, from -6% (fractured locker room) to +6% (perfect chemistry). Tiers: Fractured locker room (below 25), Tension in the group (25-44), Decent cohesion (45-64), Good cohesion (65-84), Perfect chemistry (85 and above).",
  "L'ambiance du club": "The club atmosphere",
  "L’attaque tourne à plein régime.": "The offense is firing on all cylinders.",
  "L’AVANT-": "THE PRE-",
  "L’AVANT-MATCH": "THE PRE-GAME",
  "L'effectif jeunes est déjà complet (15 stagiaires).": "The youth squad is already full (15 trainees).",
  "L'émission de la mi-temps": "The halftime show",
  "l'emporte de": "wins by",
  "L'entraîneur n'a aucun effet sur les matchs : il accélère uniquement la progression à l'entraînement (+6% par niveau). On ne l'achète plus à prix fixe : plusieurs candidats de niveaux variés sont proposés en permanence sur un": "The coach has no effect on matches: he only speeds up training progression (+6% per level). He's no longer bought at a fixed price: several candidates of varying levels are permanently available on a",
  "L'entre-deux est remporté par {0}.": "The tip-off is won by {0}.",
  "L'humeur des supporters (0 à 100, onglet dédié) influence le remplissage de votre salle et la tolérance au prix du billet : des supporters contents viennent plus facilement et acceptent des prix plus élevés. Elle évolue avec chaque résultat (victoire ou défaite, à domicile ou à l'extérieur), vos tons en interview de jalon, et dérive lentement selon que le prix des billets est jugé raisonnable ou non.": "Fan mood (0 to 100, dedicated tab) affects how full your arena gets and tolerance for ticket prices: happy fans show up more easily and accept higher prices. It changes with every result (win or loss, home or away), the tone you choose in milestone interviews, and drifts slowly depending on whether ticket prices are seen as reasonable or not.",
  "L'image de votre salle actuelle. Une salle plus grande accueille plus de spectateurs à chaque match à domicile, donc plus de recettes de billetterie.": "A picture of your current arena. A bigger arena welcomes more spectators at every home match, meaning more ticketing revenue.",
  "L'objectif de saison": "The season objective",
  "L'objectif est clair pour cette saison : on vise le haut de tableau, on ne se fixe aucune limite.": "The objective is clear for this season: we're aiming for the top of the table, no limits set.",
  "L'objectif est de construire une équipe solide et de rester compétitifs sur la durée de la saison, sans se fixer de chiffre précis pour l'instant.": "The objective is to build a solid team and stay competitive over the course of the season, without setting a precise target for now.",
  "L'onglet": "The tab",
  "La": "The",
  "La confiance du joueur, jamais liée à la fatigue. Alimentée par le ton choisi lors des interviews de jalon (voir l'onglet Humeur des supporters) : Agressif amplifie le résultat, Mesuré reste modéré, Humble limite la casse en cas de défaite.": "The player's confidence, never linked to fatigue. Fueled by the tone chosen in milestone interviews (see the Fan mood tab): Aggressive amplifies the outcome, Measured stays moderate, Humble limits the damage in case of defeat.",
  "La Coupe": "The Cup",
  "La Coupe n'existe que pour la ligue multi-manager (elle n'est pas jouée en carrière solo pour l'instant).": "The Cup only exists for the multi-manager league (it isn't played in solo career mode for now).",
