  "La liste des jeunes formés dans votre académie qui sont ensuite passés pro : un aperçu de ce que votre filière de formation a déjà produit pour le club.": "The list of youngsters trained in your academy who went on to turn pro: a look at what your development pipeline has already produced for the club.",
