  "Le championnat est lancé": "The league season is underway",
  "Le classement avant la journée": "The standings before the matchday",
  "Le classement s'affichera après les premiers matchs de championnat.": "The standings will show after the first league matches.",
  "Le classement se départage par victoires puis par différence de points. Il est découpé en zones : places 1 à 4 qualifiées pour les": "Standings are ranked by wins then by point difference. It is split into zones: places 1 to 4 qualify for the",
  "Le classement se départage par victoires puis par différence de points. Places 1 à 4 : play-offs ; 5 et 6 : maintien ; 7 et 8 : barrage ; 9 et 10 : relégation. Ce panneau résume votre position et l'écart avec les places clés.": "Standings are ranked by wins then by point difference. Places 1 to 4: playoffs; 5 and 6: safety; 7 and 8: relegation playoff; 9 and 10: relegation. This panel summarizes your position and the gap to the key places.",
  "Le club est en quasi-faillite (budget : {0}, sous {1} depuis {2} semaine(s)) : tout l'effectif a été mis en vente forcée à 1 €. Direction l'onglet": "The club is on the verge of bankruptcy (budget: {0}, below {1} for {2} week(s)): the entire squad has been forcibly put up for sale at €1. Head to the tab",
  "Le club est entre vos mains. Bonne saison, coach.": "The club is in your hands. Have a good season, coach.",
  "Le coup d'envoi est imminent.": "Tip-off is imminent.",
