  "Le match à suivre": "The match to watch",
  "le match précédent": "the previous match",
  "Le même Centre de formation que dans l'onglet Salle, mais géré directement ici : agrandissable palier par palier, il accélère la progression automatique de tous vos jeunes tant qu'ils ont moins de 18 ans.": "The same Academy as on the Arena tab, but managed directly here: upgradeable tier by tier, it speeds up the automatic progression of all your youngsters as long as they're under 18.",
  "Le moteur vise ces minutes et les ajuste seul en cas de blessure, de fautes ou de fatigue. Un poste en automatique garde la rotation habituelle.": "The engine targets these minutes and adjusts them on its own in case of injury, fouls or fatigue. A position set to automatic keeps the usual rotation.",
  "Le n°1 en fin de saison gagne 1 mois de Premium": "The #1 at the end of the season wins 1 month of Premium",
  "Le nom de la ligue doit faire entre 2 et {0} caractères.": "The league name must be between 2 and {0} characters.",
  "Le nom de la salle contient des caractères non autorisés.": "The arena name contains disallowed characters.",
  "Le nom de la salle doit faire entre 3 et {0} caractères.": "The arena name must be between 3 and {0} characters.",
  "Le nom et la capacité de votre salle actuelle, avec un bouton Agrandir pour passer au palier suivant quand vous en avez les moyens (8 paliers en tout, du Petit gymnase à l'Arena nationale).": "The name and capacity of your current arena, with an Upgrade button to move to the next tier once you can afford it (8 tiers in total, from Small gymnasium to National arena).",
  "Le numéro {0} est déjà retiré.": "Number {0} is already retired.",
  "Le poste de {poste} est désormais pourvu.": "The {poste} position is now filled.",
  "Le potentiel indique jusqu'où un joueur peut encore progresser, pas sa qualité du moment. Il ne s'affiche jamais en chiffre : seulement un": "Potential indicates how much further a player can still develop, not his current quality. It's never shown as a number: only a",
  "Le prix des billets se règle depuis l'onglet Salle, pas ici : ajustez-le pour équilibrer affluence et recettes.": "Ticket prices are set from the Arena tab, not here: adjust them to balance attendance and revenue.",
  "Le roster complet du club en une seule liste, cinq de départ en tête, puis rotation et réserve : poste, potentiel, âge, salaire, forme, motivation et évaluation des derniers matchs. Cliquez sur un nom pour ouvrir la fiche du joueur (caractéristiques, saison, Comparer, Vendre).": "The club's full roster in a single list, starting five first, then rotation and reserve: position, potential, age, salary, form, motivation and rating from recent matches. Click a name to open the player's card (attributes, season, Compare, Sell).",
