  "Le poste d'un joueur suit ses caractéristiques : dès que sa note à un autre poste dépasse nettement celle de son poste actuel, il change de poste (une nouvelle vous prévient). Les salaires (masse salariale visible sur l'onglet": "A player's position follows his attributes: as soon as his rating at another position is clearly above his current one, he switches position (a news item tells you). Salaries (payroll visible on the tab",
