  "liste tous vos matchs de la saison, championnat et Coupe confondus, groupés par mois et triés par date et heure réelle. Filtres Tous, Domicile, Extérieur et À venir ; \"vs\" devant l'adversaire signifie à domicile, \"@\" à l'extérieur. À droite : la carte du prochain match (compte à rebours et bouton des ordres) et le bilan de la saison (bilan, classement, différence de points, domicile/extérieur, forme sur les 5 derniers matchs). Les horaires restent fixes, même au changement d'heure.": "lists all your matches for the season, league and Cup combined, grouped by month and sorted by real date and time. Filters: All, Home, Away and Upcoming; \"vs\" before the opponent means home, \"@\" means away. On the right: the next match card (countdown and orders button) and the season summary (record, standings, point difference, home/away, form over the last 5 matches). Kickoff times stay fixed, even across daylight saving changes.",
