  "MENTAL": "MENTAL",
  "Mental, Endurance, Lancer franc, Puissance, Concentration, Anticipation et Leadership alimentent chacune un mécanisme de match dédié. Le Mental améliore la réussite au tir dans le money time et limite les dégâts d'une mauvaise série. L'Endurance ralentit la fatigue EN MATCH du joueur. Le Lancer franc détermine directement la réussite aux lancers francs, la Concentration l'améliore encore un peu. La Puissance augmente les fautes provoquées près du panier. L'Anticipation renforce la pression défensive de toute l'équipe sur les extérieurs. Le Leadership du MEILLEUR joueur du cinq en jeu allège, pour toute l'équipe, le malus d'une mauvaise série de tirs manqués.": "Mental, Endurance, Free throw, Power, Focus, Anticipation and Leadership each feed a dedicated in-game mechanic. Mental improves shooting success in the money time and limits the damage from a bad shooting streak. Endurance slows down the player's fatigue DURING THE GAME. Free throw directly determines free throw success, and Focus improves it a little further. Power increases fouls drawn near the basket. Anticipation boosts the whole team's defensive pressure on the perimeter. The Leadership of the BEST player in the five on court eases, for the whole team, the penalty from a bad streak of missed shots.",
  "mentalAvg": "mentalAvg",
