  "on": "on",
  "On a fait la moitié du chemin avec cette victoire contre {opponent}, mais rien n'est acquis, il reste encore beaucoup de travail avant la fin de saison.": "We're halfway there with this win against {opponent}, but nothing is guaranteed, there's still a lot of work before the season ends.",
  "On aborde la suite avec humilité, chaque adversaire mérite le plus grand respect à ce stade de la saison.": "We're approaching what's next with humility, every opponent deserves the utmost respect at this stage of the season.",
  "On aborde la suite avec l'envie de corriger ce qui n'a pas fonctionné ces dernières semaines.": "We're approaching what's next wanting to fix what hasn't worked these past few weeks.",
  "On aborde la suite avec la certitude d'avoir le niveau pour aller loin, sans aucune pression particulière.": "We're approaching what's next knowing we have what it takes to go far, with no particular pressure.",
  "On aborde la suite avec la même confiance, cette fin de saison régulière ne change rien à nos ambitions.": "We're approaching what's next with the same confidence, this end to the regular season changes nothing about our ambitions.",
  "On aborde la suite en sachant qu'il reste beaucoup de travail, on ne change rien à notre état d'esprit.": "We're approaching what's next knowing there's still a lot of work to do, we're not changing our mindset.",
  "On aborde la suite sereinement, en essayant de garder cette dynamique le plus longtemps possible.": "We're approaching what's next calmly, trying to keep this momentum going as long as possible.",
  "On accepte cette élimination avec humilité et on va travailler encore plus dur pour revenir plus forts.": "We accept this elimination with humility and we're going to work even harder to come back stronger.",
  "On cherche un partenaire stable, pas un feu de paille.": "We're looking for a stable partner, not a flash in the pan.",
  "On compte énormément sur {player} pour tirer l'équipe vers le haut, c'est un joueur fait pour ce genre de responsabilités.": "We're counting heavily on {player} to lift the team up, he's a player made for this kind of responsibility.",
  "On doit se remettre en question collectivement et travailler encore plus dur pour la seconde moitié de saison.": "We need to take a collective look at ourselves and work even harder for the second half of the season.",
  "On envoie un message clair à toute la ligue en éliminant {opponent} en demi-finale, la prochaine étape ne nous fait absolument pas peur.": "We're sending a clear message to the whole league by eliminating {opponent} in the semi-final, the next step doesn't scare us at all.",
  "On ne se fixe pas d'objectif chiffré, l'idée est de progresser ensemble match après match, en restant les pieds sur terre.": "We're not setting a numerical target, the idea is to improve together match after match, staying grounded.",
  "On passe le cap de la mi-saison sur la meilleure dynamique possible, et {opponent} vient encore de le confirmer : personne ne veut vraiment nous affronter en ce moment.": "We're crossing the midseason mark on the best possible run, and {opponent} just confirmed it again: nobody really wants to face us right now.",
  "On prépare la suite avec la même confiance, on n'a pas fait tout ce chemin pour s'arrêter en si bon chemin.": "We're preparing for what's next with the same confidence, we didn't come this far to stop now.",
  "On savait qu'on était la meilleure équipe de la division, ce titre face à {opponent} en finale ne fait que le confirmer.": "We knew we were the best team in the division, this title against {opponent} in the final only confirms it.",
  "On se retrouve après une courte pause…": "See you after a short break…",
  "On termine la saison régulière sur cette victoire contre {opponent}, et on aborde les échéances qui arrivent avec la plus grande confiance qui soit.": "We finish the regular season on this win against {opponent}, and we're approaching what's coming with all the confidence in the world.",
  "On termine la saison régulière sur une défaite décevante contre {opponent}, mais le bilan global de l'année reste ce qui compte le plus.": "We finish the regular season on a disappointing loss against {opponent}, but the overall record for the year is what matters most.",
  "On tire un trait sur cette élimination et on prépare déjà la revanche pour la saison prochaine, sans complexe.": "We're putting this elimination behind us and already preparing for revenge next season, no doubts about it.",
  "On va analyser calmement cette élimination et en tirer les enseignements pour progresser encore.": "We're going to calmly analyze this elimination and learn from it to keep improving.",
  "On va continuer à travailler dans la continuité, avec quelques ajustements tactiques pour la seconde moitié.": "We're going to keep working the same way, with a few tactical adjustments for the second half.",
  "On va continuer à travailler humblement, rien n'est jamais acquis dans ce championnat.": "We're going to keep working humbly, nothing is ever guaranteed in this league.",
  "On va préparer la suite avec sérieux, sans s'enflammer, il reste encore une marche à franchir.": "We're going to prepare for what's next seriously, without getting carried away, there's still one more step to climb.",
  "On va préparer la suite pas à pas, sans se projeter trop vite sur la suite.": "We're going to prepare for what's next step by step, without getting ahead of ourselves.",
  "On va revoir certains détails à l'entraînement pour repartir sur de meilleures bases en seconde moitié de saison.": "We're going to review a few details in training to start the second half of the season on a better footing.",
  "On veut vous voir plus haut que ce que le CA demande.": "We want to see you finish higher than what the board is asking.",
  "On vous suit sur l'objectif de la saison.": "We're watching your progress on the season objective.",
