  "Pénétration": "Penetration",
  "Pénétration, Création de tir, Interceptions, Vitesse, Accélération, Force, Détente, Décision, Sang-froid, Détermination, Discipline et Vision ont elles aussi leur mécanisme. La Pénétration aide à se créer un accès à la raquette. La Création de tir est le facteur principal de la qualité d'ouverture d'un tir. Les Interceptions pèsent dans le choix du voleur de balle. La Vitesse et l'Accélération déclenchent des contre-attaques et aident à battre son défenseur au premier pas. La Force et la Détente renforcent le rebond et le contre. La Décision réduit les pertes de balle ; la Vision améliore le choix du passeur. Le Sang-froid et la Détermination agissent comme le Mental. La Discipline réduit les fautes en défense ; un défenseur peu discipliné risque une faute antisportive, un défenseur peu serein une faute technique : deux techniques, deux antisportives, ou une de chaque dans le même match valent exclusion.": "Penetration, Shot creation, Steals, Speed, Acceleration, Strength, Vertical, Decision-making, Composure, Determination, Discipline and Vision also have their own mechanics. Penetration helps create access to the paint. Shot creation is the main factor in the openness quality of a shot. Steals weigh into who picks off the ball. Speed and Acceleration trigger fast breaks and help beat a defender off the first step. Strength and Vertical boost rebounding and blocking. Decision-making reduces turnovers; Vision improves the passer's choice. Composure and Determination work like Mental. Discipline reduces fouls on defense; an undisciplined defender risks an unsportsmanlike foul, a defender lacking composure risks a technical foul: two technicals, two unsportsmanlikes, or one of each in the same match mean ejection.",
