  "Trigramme déjà modifié récemment : prochain changement possible dans {0} jour{1}.": "Club code already changed recently: next change possible in {0} day{1}.",
  "Trigramme du club": "Club code",
  "Trigramme enregistré : {0}.": "Club code saved: {0}.",
  "Trois catégories de places (gradins, tribune, loges), chacune avec son propre prix. Un prix plus élevé rapporte plus par spectateur, mais peut réduire l'affluence si les supporters jugent que ça ne vaut pas le coup.": "Three categories of seating (bleachers, stands, boxes), each with its own price. A higher price brings in more per spectator, but can reduce attendance if fans feel it's not worth it.",
  "trop élevés": "too high",
  "true": "true",
