  "Votre équipe maîtrise plus ou moins chaque option tactique : une jauge par priorité offensive, par défense et par rythme (visible dans le menu \"Aspect travaillé\" de l'Entraînement). La maîtrise des options que vous jouez agit sur toute l'équipe en match, jusqu'à +/-6 %, en plus de l'alchimie.": "Your team masters each tactical option to a greater or lesser degree: one gauge per offensive priority, per defense and per pace (visible in the \"Focus area\" menu of Training). Mastery of the options you play affects the whole team in matches, up to +/-6%, on top of chemistry.",
