  "(tir à 3 points, mi-distance, lancer franc),": "(3-point shot, mid-range, free throw),",
  "meneurs": "playmaking",
  "(dribble, passe, création de tir, pénétration),": "(dribbling, passing, shot creation, driving),",
  "intérieurs": "big men",
  "(jeu intérieur, rebond, contre, défense intérieure) ou": "(inside game, rebounding, blocking, interior defense) or",
  "(défense extérieure, interceptions). Chaque semaine, tous les joueurs non blessés progressent un peu sur ces caractéristiques, qu'ils aient joué ou non, en plus de l'entraînement des fondamentaux. Moins sa spécialité compte de caractéristiques, plus chacune progresse vite. L'effet est surtout sensible chez les jeunes, il dépend aussi du poste et du gabarit de chaque joueur, et il est renforcé par l'entraîneur principal.": "(perimeter defense, steals). Every week, all uninjured players improve a little in these attributes, whether they played or not, on top of fundamentals training. The fewer attributes the specialty covers, the faster each one improves. The effect is mostly felt by young players, also depends on each player's position and build, and is boosted by the head coach.",
  "Entraîneur, entraîneur adjoint, analyste vidéo, recruteur, médecin, kiné : chacun a 5 niveaux, avec un coût et un effet croissants. L'analyste vidéo révèle par exemple certaines caractéristiques cachées des joueurs adverses avant un match, et le kiné réduit le risque de blessure.": "Coach, assistant coach, video analyst, scout, doctor, physio: each has 5 levels, with increasing cost and effect. The video analyst, for example, reveals certain hidden attributes of opposing players before a match, and the physio lowers the injury risk.",
  "staff médical": "medical staff",
  "s'achète sur le même marché aux enchères, avec le même salaire qui grimpe chaque semaine. Le": "is bought on the same auction market, with the same salary rising every week. The",
  "raccourcit la durée des nouvelles blessures. Le": "shortens the duration of new injuries. The",
  "suit tout l'effectif : la forme physique remonte plus vite chaque jour et le risque de blessure en match baisse (il s'ajoute à l'effet de la salle de musculation). Plus leur niveau est élevé, plus l'effet est fort.": "looks after the whole squad: physical condition recovers faster every day and the in-match injury risk drops (on top of the weight room's effect). The higher their level, the stronger the effect.",
