  "Paris ou New York": "Paris or New York",
  "… Un nouveau manager arrive dans la division la plus haute où il reste un club de l'IA ; quand tout est plein (plus de 10 managers dans un championnat), le championnat suivant s'ouvre tout seul. Les matchs se jouent à 20:00 heure locale, et tous les pays suivent les mêmes semaines.": "… A new manager joins the highest division that still has an AI club; when everything is full (more than 10 managers in a league), the next league opens on its own. Matches are played at 20:00 local time, and all countries follow the same weeks.",
  "Montées et descentes": "Promotion and relegation",
  ", décidées le lundi d'intersaison et appliquées à la reprise : le champion des play-offs de chaque championnat monte ; en face, le 10e descend, puis le 9e, puis le perdant du barrage (7e contre 8e), autant qu'il y a de championnats ouverts juste en dessous. Une prime de montée est versée au club promu.": ", decided on the off-season Monday and applied when play resumes: each league's playoff champion goes up; in return the 10th goes down, then the 9th, then the loser of the play-out (7th vs 8th), as many as there are open leagues just below. A promotion bonus is paid to the promoted club.",
  "(en bas du menu) : choisissez un pays (le vôtre par défaut) pour voir ses divisions ouvertes, son palmarès et les meilleurs joueurs de la saison. Pour afficher un autre championnat ou un club, tapez son nom dans la barre de recherche du haut (« II.2 », « Division III », un nom de club…) : classement, derniers résultats et effectif en lecture seule.": "(at the bottom of the menu): pick a country (yours by default) to see its open divisions, its honours and the season's best players. To show another league or a club, type its name in the search bar at the top (“II.2”, “Division III”, a club name…): standings, latest results and a read-only roster.",
