  // Coupe nationale (2026-09-28).
  "Coupe nationale": "National Cup",
  "Dans les championnats par pays, c'est la": "In the country leagues, it is the",
  ": tous les clubs du pays (512 au plus), avec des exempts au premier tour pour les divisions les plus hautes si le tableau n'est pas plein. Le club de la division inférieure part avec": ": every club in the country (512 at most), with first-round byes for the highest divisions when the bracket isn't full. The lower-division club starts with",
  "+7 points par division d'écart": "+7 points per division of difference",
  "(au plus +21), déjà au tableau d'affichage. Un adversaire d'un autre championnat se prépare comme les autres (Ordres, scouting) et sa fiche s'ouvre dans Planète Hoop. Chaque match de Coupe gagné rapporte une prime, de 50 000 € aux premiers tours à 400 000 € pour la finale. À l'intersaison, la": "(at most +21), already on the scoreboard. An opponent from another league is prepared like any other (Orders, scouting) and its page opens in Planet Hoop. Every Cup match won pays a bonus, from €50,000 in the early rounds to €400,000 for the final. In the off-season, the",
  "oppose le samedi à 20:00 le champion de Division I au vainqueur de la Coupe (ou au finaliste si c'est le même club), en direct et avec le même handicap : 200 000 € pour le vainqueur.": "pits the Division I champion against the Cup winner (or the runner-up if it's the same club) on Saturday at 8:00 PM, live and with the same handicap: €200,000 for the winner.",
  "Coupe nationale · {0} · saison {1} : tous les clubs du pays, un tour chaque jeudi. Le club de division inférieure part avec": "National Cup · {0} · season {1}: every club in the country, one round every Thursday. The lower-division club starts with",
  "(au plus +21), compris dans les scores.": "(at most +21), included in the scores.",
