  // Managers inactifs (2026-09-28).
  "Longue absence": "Long absence",
  ": sans aucune visite pendant 45 jours, votre club est confié à l'IA (effectif, nom et palmarès conservés). Reconnectez-vous à votre compte pour le récupérer, s'il n'a pas été repris entre-temps par un autre manager ; sinon un nouveau club vous est attribué.": ": after 45 days without a single visit, your club is handed to the AI (roster, name and honours kept). Log back into your account to get it back, unless another manager has taken it over in the meantime; otherwise you're given a new club.",
  "Bon retour à {0} !": "Welcome back to {0}!",
  "Pendant votre absence, le club a été géré par l'IA. Vérifiez votre effectif, vos ordres et votre budget.": "While you were away, the club was run by the AI. Check your roster, your orders and your budget.",
  // Amicaux entre championnats (2026-09-28).
  "Contre un club d'un autre championnat": "Against a club from another league",
  ", même d'un autre pays : tapez son nom dans la recherche d'adversaire, les clubs du monde entier apparaissent sous ceux de votre ligue (drapeau et division). Mêmes règles : jour de repos des deux clubs, heure de Paris, invitation à accepter contre un manager (il est prévenu dans son fil d'actualité).": ", even from another country: type its name in the opponent search, clubs from all over the world show up below those of your league (flag and division). Same rules: a rest day for both clubs, Paris time, an invitation to accept against a manager (they're notified in their news feed).",
  "Club d'un autre championnat ({0}) : l'amical se joue à la même heure (Paris) pour les deux clubs.": "Club from another league ({0}): the friendly is played at the same time (Paris) for both clubs.",
  "Autre championnat": "Another league",
  "Un des deux clubs a changé de championnat.": "One of the two clubs changed leagues.",
  "Adversaire du même championnat : passez par la liste habituelle.": "Opponent from the same league: use the usual list.",
  // Marché mondial (2026-09-28).
  "Monde entier": "Whole world",
  "Mon pays": "My country",
  "Mon championnat": "My league",
  "Marché mondial": "World market",
  ": les annonces de tous les championnats, dans tous les pays, apparaissent aussi (drapeau et division du vendeur sur la carte ; filtre « Monde entier », « Mon championnat » ou le pays de votre choix, avec une recherche). On y enchérit de la même façon ; le joueur rejoint votre club à la clôture de l'enchère. Les annonces des autres championnats se mettent à jour toutes les quelques minutes : si quelqu'un a surenchéri entre-temps, votre enchère est refusée et le prix actualisé.": ": listings from every league, in every country, show up too (the seller's flag and division on the card; “Whole world”, “My league” or any country you like, with a search box). You bid the same way; the player joins your club when the auction closes. Listings from other leagues refresh every few minutes: if someone outbid you in the meantime, your bid is refused and the price updated.",
