  "À la fin de la saison régulière, la ligue décerne ses": "At the end of the regular season, the league hands out its",
  "récompenses": "awards",
  ": MVP, 5 majeur (un joueur par poste), meilleur jeune (21 ans ou moins), 6e homme (un joueur surtout remplaçant) et meilleur défenseur, puis le": ": MVP, All-League five (one player per position), best young player (21 or younger), sixth man (a player who mostly comes off the bench) and best defender, then the",
  "(dans l'équipe championne) après la finale. Elles se calculent sur la saison régulière, pour les joueurs qui ont disputé au moins 40 % des journées, et s'affichent dans l'onglet Ligue.": "(from the champion team) after the final. They are calculated over the regular season, for players who played at least 40% of the matchdays, and are shown in the League tab.",
  "À mi-saison, le dimanche à 20h, les 10 meilleurs joueurs du pays affrontent les 10 meilleurs étrangers lors du": "At mid-season, on Sunday at 8pm, the country's 10 best players face the 10 best foreign players in the",
