  "Ces ordres valent pour tous vos matchs de ligue privée à venir, jamais pour les matchs officiels. Sans ordres enregistrés, la ligue privée se joue avec les ordres actuels du club.": "These orders apply to all your upcoming private league matches, never to official matches. Without saved orders, the private league is played with the club's current orders.",
