  "Tactique × {0}": "Tactics × {0}",
  "Récupération × {0}": "Recovery × {0}",
  "Physique × {0}": "Physical × {0}",
  "Blessé à l'entraînement": "Injured in training",
  "{0} n'a joué que {1} min cette semaine sur {2} : son plan ne compte qu'à {3} %.": "{0} only played {1} min this week out of {2}: his plan only counts at {3}%.",
  "Forme moyenne de l'équipe": "Team average fitness",
  "Plans individuels.": "Individual plans.",
  "Chaque place de plan associe un joueur à un programme parmi les 13 fondamentaux (tir, passe, défense, etc.), quel que soit son poste. Le nombre de places dépend de l'entraîneur : 3 aux niveaux 1 et 2, 4 aux niveaux 3 et 4, 5 au niveau 5. Sans entraîneur, aucun fondamental n'est travaillé. L'entraînement se déclenche le lundi à 6h, heure de Paris.": "Each plan slot pairs a player with a program among the 13 fundamentals (shooting, passing, defense, etc.), whatever his position. The number of slots depends on the coach: 3 at levels 1 and 2, 4 at levels 3 and 4, 5 at level 5. Without a coach, no fundamental is trained. Training runs on Monday at 6am, Paris time.",
  "Rendement.": "Training rate.",
  "Un joueur en plan doit avoir joué 30 minutes dans la semaine (championnat, Coupe, play-offs et amicaux) pour un plein rendement, moins s'il a peu joué. L'âge (les jeunes apprennent plus vite), le gabarit, le niveau de l'entraîneur et l'intensité de la semaine font varier le rendement, affiché en % pour chaque joueur. Le poste n'a plus d'effet.": "A player in a plan must have played 30 minutes during the week (league, Cup, playoffs and friendlies) for the full rate, less if he barely played. Age (youngsters learn faster), build, coach level and weekly intensity change the rate, shown as a % for each player. Position no longer matters.",
  "Intensité.": "Intensity.",
  "Légère : progression plus lente, meilleure récupération. Normale. Intense : progression plus rapide, mais forme en baisse et petit risque de blessure pour les joueurs en plan.": "Light: slower progress, better recovery. Normal. Intense: faster progress, but lower fitness and a small injury risk for players in a plan.",
  "Plafond.": "Ceiling.",
  "Chaque joueur a une marge de progression propre ; quand elle se réduit, la progression ralentit peu à peu, sans s'arrêter net. Un bon entraîneur repousse ce plafond. Quand un joueur ne progresse plus, le bilan du lundi propose un autre programme (bouton Appliquer).": "Each player has his own room for improvement; as it shrinks, progress slows down gradually, without stopping dead. A good coach pushes this ceiling back. When a player stops improving, the Monday report suggests another program (Apply button).",
  "Spécialités de l'entraîneur.": "Coach specialties.",
  "Attaque ou Défense : programmes de cette famille plus efficaces. Physique : jours Physique plus efficaces. Jeunes : joueurs de 21 ans et moins, et académie, plus efficaces.": "Offense or Defense: programs of that family are more effective. Physical: Physical days are more effective. Youth: players aged 21 and under, and the academy, train more effectively.",
  "Collectif.": "Team training.",
  "Chaque jour sans match officiel, choisissez Tactique (un aspect précis : une priorité offensive, une défense ou un rythme ; plus il est neuf, plus il progresse vite), Récupération (forme en hausse pour tout l'effectif) ou Physique (petit gain physique, surtout pour les jeunes). Un jour d'amical, la tactique n'est pas possible, mais les joueurs non retenus pour l'amical peuvent récupérer ou faire du physique.": "On each day without an official game, choose Tactics (one specific aspect: an offensive priority, a defense or a pace; the newer it is, the faster it improves), Recovery (fitness up for the whole squad) or Physical (small physical gain, mostly for youngsters). On a friendly day, tactics are not possible, but players not selected for the friendly can recover or do physical work.",
  "Mental et parrainage.": "Mental and mentoring.",
  "Le mental progresse en partie tout seul, en partie avec les minutes jouées dans la semaine. Un jeune (22 ans au plus) associé à un vétéran (29 ans au moins) du même poste progresse plus vite au mental (2 parrainages au plus).": "Mental attributes improve partly on their own, partly with minutes played during the week. A youngster (22 at most) paired with a veteran (29 or older) at the same position improves mentally faster (2 mentoring pairs at most).",
  "Chaque semaine (le lundi à 6h), vos joueurs en plan individuel travaillent le programme choisi pour eux parmi les 13 fondamentaux. Le nombre de places dépend de votre entraîneur (3 à 5) : sans entraîneur, pas de travail des fondamentaux. Le Physique et le Mental évoluent tout seuls, le Mental aussi avec les minutes jouées.": "Every week (Monday at 6am), your players with an individual plan work on the program chosen for them among the 13 fundamentals. The number of slots depends on your coach (3 to 5): without a coach, no fundamentals work. Physical and Mental attributes develop on their own, Mental also with minutes played.",
  "Un joueur en plan doit jouer 30 minutes dans la semaine (championnat, Coupe, play-offs et amicaux) pour un plein rendement ; le poste n'a plus d'importance.": "A player in a plan must play 30 minutes during the week (league, Cup, playoffs and friendlies) for the full rate; position no longer matters.",
  "Chaque jour sans match, choisissez Tactique (un aspect précis), Récupération (forme +15) ou Physique (petit gain physique, surtout pour les jeunes). Un jour d'amical, les joueurs non retenus peuvent récupérer ou faire du physique.": "Each day without a game, choose Tactics (one specific aspect), Recovery (fitness +15) or Physical (small physical gain, mostly for youngsters). On a friendly day, players not selected can recover or do physical work.",
  "Une tactique neuve s'apprend vite (+12 par jour à 40), une tactique déjà maîtrisée beaucoup moins (+4 par jour à 95). Le détail est dans le Guide.": "A new tactic is learned quickly (+12 per day at 40), an already mastered one much less (+4 per day at 95). Details are in the Guide.",
  // Entraînement v2 (retour utilisateur 2026-10-01).
  "+{0}/jour": "+{0}/day",
  "Votre équipe maîtrise plus ou moins chaque option tactique : une jauge par priorité offensive, par défense et par rythme (visible dans le menu \"Aspect travaillé\" de l'Entraînement). La maîtrise des options que vous jouez agit sur toute l'équipe en match, jusqu'à +/-8 %, en plus de l'alchimie.": "Your team masters each tactical option to a greater or lesser degree: one gauge per offensive priority, per defense and per pace (visible in the \"Focus area\" menu of Training). Mastery of the options you play affects the whole team in matches, up to +/-8%, on top of chemistry.",
  "sur cette option la fait monter à chaque jour de repos écoulé, selon son niveau : +12 par jour à 40, +9 à 60, +6 à 80, +4 à 95 (jamais un jour d'amical). Un": "on this option raises it on each elapsed rest day, depending on its level: +12 per day at 40, +9 at 60, +6 at 80, +4 at 95 (never on a friendly day). A",
